/**
 * Build script for dsh-whale-pet.
 * Compiles TypeScript source to lib/ and bundles the client artifact
 * matching DSH Client Module specifications.
 * Inlines character PNGs as base64 Data URIs to eliminate 404s in DSH Desktop & Web.
 */

import { readFileSync, writeFileSync, mkdirSync, cpSync, existsSync, renameSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import ts from 'typescript'

const __dirname = dirname(fileURLToPath(import.meta.url))

const srcAssetsDir = join(__dirname, 'assets')
mkdirSync(srcAssetsDir, { recursive: true })

console.log('[build] 1. Syncing latest character files from 大肥鱼表情...')
const expressionDirs = [
  'C:/Users/etern/OneDrive/Desktop/大肥鱼表情',
  'C:/Users/etern/Desktop/大肥鱼表情',
]

for (const exprDir of expressionDirs) {
  if (existsSync(exprDir)) {
    const files = [
      'Maid.png', 'DaFeiYu.png', 'Answering.png', 'baifan.png',
      'getit.png', 'sajiao.png', 'Think1.png', 'Think2.png',
      'Think3.png', 'Think4.png', 'Think5.png'
    ]
    for (const file of files) {
      const src = join(exprDir, file)
      if (existsSync(src)) {
        cpSync(src, join(srcAssetsDir, file))
      }
    }
  }
}

console.log('[build] 2. Generating src/client/assets-data.ts with base64 Data URIs...')
const maidB64 = readFileSync(join(srcAssetsDir, 'Maid.png')).toString('base64')
const chibiB64 = readFileSync(join(srcAssetsDir, 'DaFeiYu.png')).toString('base64')
const answeringB64 = readFileSync(join(srcAssetsDir, 'Answering.png')).toString('base64')
const baifanB64 = readFileSync(join(srcAssetsDir, 'baifan.png')).toString('base64')
const getitB64 = readFileSync(join(srcAssetsDir, 'getit.png')).toString('base64')
const sajiaoB64 = readFileSync(join(srcAssetsDir, 'sajiao.png')).toString('base64')
const think1B64 = readFileSync(join(srcAssetsDir, 'Think1.png')).toString('base64')
const think2B64 = readFileSync(join(srcAssetsDir, 'Think2.png')).toString('base64')
const think3B64 = readFileSync(join(srcAssetsDir, 'Think3.png')).toString('base64')
const think4B64 = readFileSync(join(srcAssetsDir, 'Think4.png')).toString('base64')
const think5B64 = readFileSync(join(srcAssetsDir, 'Think5.png')).toString('base64')

const maidDataUri = `data:image/png;base64,${maidB64}`
const chibiDataUri = `data:image/png;base64,${chibiB64}`
const answeringDataUri = `data:image/png;base64,${answeringB64}`
const baifanDataUri = `data:image/png;base64,${baifanB64}`
const getitDataUri = `data:image/png;base64,${getitB64}`
const sajiaoDataUri = `data:image/png;base64,${sajiaoB64}`
const think1DataUri = `data:image/png;base64,${think1B64}`
const think2DataUri = `data:image/png;base64,${think2B64}`
const think3DataUri = `data:image/png;base64,${think3B64}`
const think4DataUri = `data:image/png;base64,${think4B64}`
const think5DataUri = `data:image/png;base64,${think5B64}`

const assetsDataTs = `/**
 * Embedded character image Data URIs for dsh-whale-pet.
 * Generated by build.js from assets/ (大肥鱼表情).
 * Eliminates 404 network errors in DSH desktop & web environments.
 */
export const MAID_DATA_URI = ${JSON.stringify(maidDataUri)}
export const MAIDEN_DATA_URI = MAID_DATA_URI
export const CHIBI_DATA_URI = ${JSON.stringify(chibiDataUri)}
export const ANSWERING_DATA_URI = ${JSON.stringify(answeringDataUri)}
export const BAIFAN_DATA_URI = ${JSON.stringify(baifanDataUri)}
export const GETIT_DATA_URI = ${JSON.stringify(getitDataUri)}
export const SAJIAO_DATA_URI = ${JSON.stringify(sajiaoDataUri)}
export const MAD_DATA_URI = SAJIAO_DATA_URI
export const THINK1_DATA_URI = ${JSON.stringify(think1DataUri)}
export const THINK2_DATA_URI = ${JSON.stringify(think2DataUri)}
export const THINK3_DATA_URI = ${JSON.stringify(think3DataUri)}
export const THINK4_DATA_URI = ${JSON.stringify(think4DataUri)}
export const THINK5_DATA_URI = ${JSON.stringify(think5DataUri)}
`
const generatedAssetsPath = join(__dirname, 'src', 'client', 'assets-data.ts')
if (!existsSync(generatedAssetsPath) || readFileSync(generatedAssetsPath, 'utf-8') !== assetsDataTs) writeFileSync(generatedAssetsPath, assetsDataTs, 'utf-8')

console.log('[build] 3. Running TypeScript compiler...')
const configPath = join(__dirname, 'tsconfig.json')
const config = ts.readConfigFile(configPath, ts.sys.readFile)
if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, '\n'))
const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, __dirname)
const compilerHost = ts.createCompilerHost(parsed.options)
// Avoid rewriting unchanged multi-megabyte embedded assets on every UI edit.
compilerHost.writeFile = (path, contents) => {
  if (existsSync(path) && readFileSync(path, 'utf-8') === contents) return
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, contents, 'utf-8')
}
const program = ts.createProgram(parsed.fileNames, parsed.options, compilerHost)
const diagnostics = [...parsed.errors, ...ts.getPreEmitDiagnostics(program)]
if (diagnostics.some(diagnostic => diagnostic.category === ts.DiagnosticCategory.Error)) {
  throw new Error(ts.formatDiagnosticsWithColorAndContext(diagnostics, {
    getCurrentDirectory: () => __dirname,
    getCanonicalFileName: path => path,
    getNewLine: () => '\n',
  }))
}
const emit = program.emit()
if (emit.emitSkipped) throw new Error('TypeScript emit was skipped')

console.log('[build] 4. Ensuring lib/assets directory...')
const libAssetsDir = join(__dirname, 'lib', 'assets')
mkdirSync(libAssetsDir, { recursive: true })
cpSync(srcAssetsDir, libAssetsDir, { recursive: true })

console.log('[build] 5. Bundling lib/client.js for DSH browser module loader...')
const petOverlayCss = readFileSync(join(__dirname, 'src', 'client', 'PetOverlay.module.css'), 'utf-8')
const galgameCss = readFileSync(join(__dirname, 'src', 'client', 'galgame.css'), 'utf-8')
const puppetCss = readFileSync(join(__dirname, 'src', 'client', 'LivingPuppet.module.css'), 'utf-8')
const fullCss = `${petOverlayCss}\n${galgameCss}\n${puppetCss}`

// Embed compiler output to keep state and host integration identical in both entry points.
const stateMachineSource = readFileSync(join(__dirname, 'lib/client/state-machine.js'), 'utf-8')
  .replace(/^export /gm, '').replace(/^\/\/# sourceMappingURL=.*$/gm, '')
const clientAdapterSource = readFileSync(join(__dirname, 'lib/client/index.js'), 'utf-8')
  .replace(/^import .*$/gm, '').replace(/^export /gm, '')
  .replace(/^\/\/# sourceMappingURL=.*$/gm, '')

// Compile both React views into the template, using the same source as type checking.
function compileView(file, component) {
  const source = readFileSync(join(__dirname, 'src/client', file), 'utf-8').replace(/^import[\s\S]*?from ['"][^'"]+['"]\s*$/gm, '')
  const code = ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext, jsx: ts.JsxEmit.React } }).outputText.replace(/^export /gm, '')
  return 'const ' + component + ' = (() => { const styles = new Proxy({}, { get: (_, key) => key });\n' + code + '\nreturn ' + component + '; })();'
}
const experienceSource = readFileSync(join(__dirname, 'lib/client/experience.js'), 'utf-8').replace(/^export /gm, '')
const dialogueView = compileView('DialogueContent.tsx', 'DialogueContent')
const puppetView = compileView('LivingPuppet.tsx', 'LivingPuppet')
const overlayView = compileView('PetOverlay.tsx', 'PetOverlay')
const preferencesSource = readFileSync(join(__dirname, 'lib/client/preferences.js'), 'utf-8').replace(/^export /gm, '')

const clientBundleSource = `/**
 * dsh-whale-pet browser client bundle.
 * Self-contained Cordis Web UI client plugin.
 */
(function() {
  if (typeof window === 'undefined' || !window.__ModuleLoader__) {
    return;
  }

  window.__ModuleLoader__.load({
    id: 'dsh-whale-pet',
    factory: function(require) {
      const React = require('react');
      const h = React.createElement;
      const useState = React.useState;
      const useEffect = React.useEffect;
      const useRef = React.useRef;
      const useCallback = React.useCallback;
      const useMemo = React.useMemo;

      // Inject styles into document head on materialization
      let styleEl = document.getElementById('dsh-whale-pet-styles');
      if (!styleEl) {
        styleEl = document.createElement('style');
        styleEl.id = 'dsh-whale-pet-styles';
        styleEl.textContent = ${JSON.stringify(fullCss)};
        document.head.appendChild(styleEl);
      }

      ${stateMachineSource}

      const MAIDEN_PATH = ${JSON.stringify(maidDataUri)};
      const CHIBI_PATH = ${JSON.stringify(chibiDataUri)};
      const ANSWERING_PATH = ${JSON.stringify(answeringDataUri)};
      const BAIFAN_PATH = ${JSON.stringify(baifanDataUri)};
      const GETIT_PATH = ${JSON.stringify(getitDataUri)};
      const SAJIAO_PATH = ${JSON.stringify(sajiaoDataUri)};
      const THINK1_PATH = ${JSON.stringify(think1DataUri)};
      const THINK2_PATH = ${JSON.stringify(think2DataUri)};
      const THINK3_PATH = ${JSON.stringify(think3DataUri)};
      const THINK4_PATH = ${JSON.stringify(think4DataUri)};
      const THINK5_PATH = ${JSON.stringify(think5DataUri)};

const MAID_DATA_URI = MAIDEN_PATH;
const CHIBI_DATA_URI = CHIBI_PATH;
const ANSWERING_DATA_URI = ANSWERING_PATH;
const BAIFAN_DATA_URI = BAIFAN_PATH;
const GETIT_DATA_URI = GETIT_PATH;
const SAJIAO_DATA_URI = SAJIAO_PATH;
const THINK1_DATA_URI = THINK1_PATH;
const THINK2_DATA_URI = THINK2_PATH;
const THINK3_DATA_URI = THINK3_PATH;
const THINK4_DATA_URI = THINK4_PATH;
const THINK5_DATA_URI = THINK5_PATH;
      ${preferencesSource}
      ${experienceSource}
      ${dialogueView}
      ${puppetView}
      ${overlayView}
      ${clientAdapterSource}
      return {
        inject,
        apply(ctx) {
          apply(ctx);
          ctx.effect(() => () => styleEl.remove());
        },
      };
    },
  });
})();
`

const libClientPath = join(__dirname, 'lib', 'client.js')
const bundleTemporaryPath = libClientPath + '.tmp'
writeFileSync(bundleTemporaryPath, clientBundleSource.replace(/^[ \t]+$/gm, ''), 'utf-8')
renameSync(bundleTemporaryPath, libClientPath)
console.log(`[build] Successfully generated ${libClientPath}`)
